## Approach
- Maintain an array where every number is a prime
- Loop on each number and mark every multiple of that number as prime = false
- Create a new array of numbers where prime = true
- This array will contain all the prime numbers

## Solution
```go[]

func primeTillN(n int) []int {
	allPrimes := make([]bool, n+1)

	for i := 2; i <= n; i++ {
		allPrimes[i] = true
	}

	for i := 2; i*i <= n; i++ {
		for j := i * i; j <= n; j += i {
			if allPrimes[j] {
				allPrimes[j] = false
			}
		}

	}

	primes := []int{}
	for i := 0; i <= n; i++ {
		if allPrimes[i] {
			primes = append(primes, i)
		}
	}
	return primes
}
```

